let tree = null;

/** Map mã tỉnh cũ -> [{ name, wards: [{ name, newProvinceId, newWard }] }] */
function oldTree() {
  if (tree) return tree;
  tree = new Map();
  const defNew = new Map(VTP_OLD_PROVINCES.map(([id, , nid]) => [id, nid]));
  for (const line of VTP_OLD_RAW.split('\n')) {
    const eq = line.indexOf('=');
    const pid = Number(line.slice(0, eq));
    const districts = line
      .slice(eq + 1)
      .split('|')
      .map((part) => {
        const colon = part.indexOf(':');
        const wards = part
          .slice(colon + 1)
          .split(',')
          .map((item) => {
            const [name, ref] = item.split('>');
            const dot = ref.indexOf('.');
            const newProvinceId = dot < 0 ? defNew.get(pid) : Number(ref.slice(0, dot));
            const idx = Number(dot < 0 ? ref : ref.slice(dot + 1));
            return { name, newProvinceId, newWard: vtpWardsOf(newProvinceId)[idx] };
          });
        return { name: part.slice(0, colon), wards };
      });
    tree.set(pid, districts);
  }
  return tree;
}

/** Quận/huyện của một tỉnh cũ, tên như "Q.1", "H.Lộc Hà". */
export function vtpOldDistrictsOf(provinceId) {
  return (oldTree().get(Number(provinceId)) || []).map((x) => x.name);
}

/** Phường/xã của một quận/huyện cũ, tên như "P.Bến Nghé", "X.Thạch Kim", "TT.Lăng Cô". */
export function vtpOldWardsOf(provinceId, districtName) {
  const dist = (oldTree().get(Number(provinceId)) || []).find((x) => x.name === districtName);
  return dist ? dist.wards.map((x) => x.name) : [];
}

const OLD_PREFIX = [
  [/^(thanh pho|tp)\s+/, ''],
  [/^(tinh|t)\s+/, ''],
  [/^(quan|q)\s+/, ''],
  [/^(huyen|h)\s+/, ''],
  [/^(thi xa|tx)\s+/, ''],
  [/^(phuong|p)\s+/, ''],
  [/^(thi tran|tt)\s+/, ''],
  [/^(xa|x)\s+/, '']
];

/** Loại cấp hành chính để "Quận 1" không khớp nhầm "H.1"; "TP." của quận khác "TP." của tỉnh. */
function kindOf(s) {
  const n = normalizeVN(s.replace(/\./g, '. '));
  if (/^(thanh pho|tp)\b/.test(n)) return 'tp';
  if (/^(tinh|t)\b/.test(n)) return 't';
  if (/^(quan|q)\b/.test(n)) return 'q';
  if (/^(huyen|h)\b/.test(n)) return 'h';
  if (/^(thi xa|tx)\b/.test(n)) return 'tx';
  if (/^(phuong|p)\b/.test(n)) return 'p';
  if (/^(thi tran|tt)\b/.test(n)) return 'tt';
  if (/^(xa|x)\b/.test(n)) return 'x';
  return '';
}

/** Tên bỏ dấu, bỏ tiền tố cấp, "Phường 01" = "P.1". Chữ "Ð" (eth) của Viettel Post coi như "Đ". */
export function oldKey(s) {
  let n = normalizeVN(String(s || '').replace(/Ð/g, 'Đ').replace(/\./g, '. '));
  for (const [re] of OLD_PREFIX) {
    if (re.test(n)) {
      n = n.replace(re, '');
      break;
    }
  }
  return n.replace(/\b0+(\d)/g, '$1').replace(/\s+/g, ' ').trim();
}

/** Không tiền tố, tên tự nhiên (như "Quan Hoa"): so cả bản chưa bỏ tiền tố. */
const plainKey = (s) => normalizeVN(String(s || '').replace(/Ð/g, 'Đ')).replace(/\b0+(\d)/g, '$1');

function sameName(a, b) {
  const ka = oldKey(a);
  const kb = oldKey(b);
  return ka === kb || ka === plainKey(b) || plainKey(a) === kb;
}

function sameUnit(a, b, kinds) {
  if (!sameName(a, b)) return false;
  const ka = kindOf(a);
  const kb = kindOf(b);
  return !ka || !kb || ka === kb || (kinds && kinds.includes(ka) && kinds.includes(kb));
}

/**
 * Đúng cấp trước ("Q.1" chứ không phải "H.1"); không có thì chấp nhận khác cấp nếu tên chỉ có một,
 * vì đơn cũ hay còn ghi "X.Bình Khê" trong khi Viettel Post đã đổi thành "P.Bình Khê".
 */
function pickUnit(list, name) {
  const exact = list.find((x) => sameUnit(x.name, name));
  if (exact) return exact;
  const loose = list.filter((x) => sameName(x.name, name));
  return loose.length === 1 ? loose[0] : null;
}

/**
 * Tìm địa chỉ cũ trong danh mục Viettel Post, chấp nhận cách viết khác ("Phường Tân Định, Quận 1, TP. Hồ Chí Minh").
 * Trả về tên chuẩn Viettel Post và phường mới tương ứng, hoặc null.
 */
export function findVtpOldAddress({ province, district, ward } = {}) {
  if (!province || !district || !ward) return null;
  const provs = VTP_OLD_PROVINCES.filter(([, name]) => sameUnit(name, province, ['t', 'tp']));
  for (const [pid, pName] of provs) {
    const dist = pickUnit(oldTree().get(pid) || [], district);
    if (!dist) continue;
    const w = pickUnit(dist.wards, ward);
    if (!w) continue;
    const newProv = VTP_PROVINCES.find(([id]) => id === w.newProvinceId);
    return {
      province: pName,
      district: dist.name,
      ward: w.name,
      newProvince: newProv ? newProv[1] : '',
      newWard: w.newWard || ''
    };
  }
  return null;
}

/** Địa chỉ mới (2 cấp) viết hơi khác ("TP. Hà Nội", "Phường Yên Hòa") vẫn ra đúng tên Viettel Post. */
export function findVtpNewAddress({ province, ward } = {}) {
  const prov = VTP_PROVINCES.find(([, name]) => name === province) || vtpProvinceByName(province);
  if (!prov || !ward) return null;
  const wards = vtpWardsOf(prov[0]);
  const hit = wards.includes(ward) ? ward : wards.find((w) => normalizeVN(w) === normalizeVN(ward));
  return hit ? { province: prov[1], ward: hit } : null;
}

/**
 * Địa chỉ của khách có xuất sang Viettel Post được không, và viết ra sao.
 * Có quận/huyện là địa chỉ cũ (3 cấp), không có là địa chỉ mới (2 cấp), giống công tắc trong app.
 * Trả về { ok, reason, mode, province, district, ward, street, line }.
 */
export function resolveVtpAddress({ province, district, ward, street } = {}) {
  const st = String(street || '').trim();
  const isOld = !!String(district || '').trim();
  const out = { ok: false, reason: '', mode: isOld ? 'old' : 'new', province: '', district: '', ward: '', street: st, line: '' };
  if (isOld) {
    const r = findVtpOldAddress({ province, district, ward });
    if (!r) {
      out.reason = 'Địa chỉ cũ không có trong danh mục Viettel Post, chọn lại';
      return out;
    }
    Object.assign(out, { province: r.province, district: r.district, ward: r.ward, newProvince: r.newProvince, newWard: r.newWard });
  } else {
    if (!province) {
      out.reason = 'Chưa chọn tỉnh/thành theo Viettel Post';
      return out;
    }
    const r = findVtpNewAddress({ province, ward });
    if (!r) {
      out.reason = 'Chưa chọn phường/xã theo Viettel Post';
      return out;
    }
    Object.assign(out, r);
  }
  if (!st) {
    out.reason = 'Thiếu số nhà, tên đường';
    return out;
  }
  out.ok = true;
  out.line = [st, out.ward, out.district, out.province].filter(Boolean).join(', ');
  return out;
}
